def split_on_commas(x):
    splits = [None]
    open = False
    for char in x:
        if char == '{':
            open = True
        elif char == '}' and open is not False:
            open = False
        if char == ',' and open is False:
            splits.append(None)
        else:
            if splits[-1] is None:
                splits.append([char])
            else:
